    private static ReadOnlySpan<byte> _Advanced_GPU_Shader() =>
    """
    fn cross2d(a: vec2<f32>, b: vec2<f32>) -> f32 { return a.x * b.y - a.y * b.x; }
    fn distanceSquared2(a: vec2<f32>, b: vec2<f32>) -> f32 { let d = a - b; return dot(d, d); }

    struct Advanced_Uniforms {
        count      : u32,           // offset:  0 size:  4
    };                              //            size: 16
    
    @group(0) @binding(0) var<storage, read_write>  position_arr: array<vec2<f32>>;
    @group(0) @binding(1) var<storage, read      >  velocity_arr: array<vec2<f32>>;

    @group(1) @binding(0) var<uniform>              uniforms: Advanced_Uniforms;

    @compute @workgroup_size(64)
    fn Advanced(@builtin(global_invocation_id) global_id: vec3<u32>)
    {
        let index = global_id.x;
        if (index >= uniforms.count) {
            return;
        }
        var _position = position_arr[index];
        var _velocity = velocity_arr[index];

        var _cross = cross2d(_position, _velocity);
        var _normalize = normalize(_velocity);
        var _length = length(_position);
        var _dist = distance(_position, _velocity);
        var _distSquared = distanceSquared2(_position, _velocity);
        var _sum = (((_cross + _length) + _dist) + _distSquared);
        _position = (_sum * _normalize);

        position_arr[index] = _position;
    }
